const texto = $input.item.json.messageBody || '';

// Decodificar URL encoding y limpiar ofuscación básica
const decodificado = decodeURIComponent(texto.replace(/\+/g, ' '));
const sinEspacios = decodificado.replace(/[\s\/*\-]+/g, ' ').trim();
const sinComentarios = sinEspacios.replace(/\/\*.*?\*\//gs, ' ').replace(/--[^\n]*/g, ' ');

// Detectar base64 sospechoso (bloques largos de base64 que podrían ser payloads)
const base64Pattern = /[A-Za-z0-9+/]{40,}={0,2}/;

const patrones = [
  // SQL estándar
  /\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|TRUNCATE|UNION|FROM|WHERE|INTO|TABLE|DATABASE|EXEC|EXECUTE|CAST|CONVERT)\b/i,
  // SQL ofuscado con saltos o comentarios limpiados
  /S[\s]*E[\s]*L[\s]*E[\s]*C[\s]*T/i,
  /D[\s]*R[\s]*O[\s]*P/i,
  /U[\s]*N[\s]*I[\s]*O[\s]*N/i,
  // Inyección clásica
  /(\'|\")(\s)*(OR|AND)(\s)+(\d+|\'\d+\'|\".*\")(\s)*(=|LIKE)/i,
  /(\bOR\b|\bAND\b)\s+[\'\"]?\d+[\'\"]?\s*=\s*[\'\"]?\d+[\'\"]?/i,
  // Comentarios SQL
  /(--|\/\*|\*\/|;\s*(DROP|SELECT|INSERT|UPDATE|DELETE))/i,
  // CHAR() y concatenación
  /CHAR\s*\(\s*\d+\s*\)/i,
  /(0x[0-9a-fA-F]{2,})/,
  // HTML/Scripts
  /<\s*\/?\s*(script|html|body|iframe|form|input|img)[^>]*>/i,
  // JavaScript
  /\b(eval\s*\(|document\.|window\.|setTimeout|setInterval|Function\s*\()\b/i,
  // Python
  /\b(import\s+\w+|def\s+\w+\s*\(|__import__\s*\(|exec\s*\()\b/i,
  // Shell
  /(\$\(|`[^`]{0,200}`|\|\s*(bash|sh|cmd|powershell)|rm\s+-|chmod\s+|sudo\s+|wget\s+|curl\s+http)/i,
  // URL encoding de palabras clave SQL
  /(%53%45%4C%45%43%54|%44%52%4F%50|%49%4E%53%45%52%54|%55%4E%49%4F%4E)/i,
];

const textosAChequear = [texto, decodificado, sinComentarios];
const esCodigo = textosAChequear.some(t => patrones.some(p => p.test(t))) || base64Pattern.test(texto);

if (esCodigo) {
  return [{ json: { text: '', codigo: true } }];
}

return [{ json: { ...$input.item.json, codigo: false } }];

const parsed = $input.item.json;
const cantidad_personas = parsed.cantidad_personas || null;
const derivar_a_vendedor_fechas = parsed.derivar_a_vendedor || false;

// DERIVAR A VENDEDOR por cantidad de personas
let derivar_a_vendedor = derivar_a_vendedor_fechas;
if (!derivar_a_vendedor && cantidad_personas !== null) {
  if (Number(cantidad_personas) === 1 || Number(cantidad_personas) >= 4) {
    derivar_a_vendedor = true;
  }
}

return [{ json: {
  ...parsed,
  derivar_a_vendedor
}}];

const raw = $input.item.json.output;
const clean = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(clean);

return [{ json: parsed }];

// Normaliza la respuesta de Redis (LRANGE puede devolver array o string suelto)
const raw = $input.first().json.message;
const list = Array.isArray(raw) ? raw : (raw ? [raw] : []);

let lastMessageId = null;
let lastTimestamp = null;
let parseError = false;

if (list.length > 0) {
  try {
    const last = JSON.parse(list[list.length - 1]);
    lastMessageId = last.message_id || null;
    lastTimestamp = last.timestamp || null;
  } catch (e) {
    parseError = true;
  }
}

return [{ json: {
  ...$input.first().json,
  list,
  lastMessageId,
  lastTimestamp,
  parseError,
  count: list.length
}}];

const fecha_entrada = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.fecha_entrada || null;
const fecha_salida = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.fecha_salida || null;
const cantidad_personas = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.cantidad_personas || null;
const derivar_a_vendedor = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.derivar_a_vendedor || false;
const count = parseInt($('Revisión del historial').first().json.COUNT) || 0;
const primer_mensaje = count === 0;
const messages = $('Aggregate').first().json.text?.[0] || '';
const error_temporada = $('Merge3').first().json.error_temporada || 0;
const precio_total = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.precio || null;
const nombre_cliente = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.nombre_cliente || null;

let calendarid = null;
try {
  calendarid = $('Revisar  CP, E, S, T, DV, PI, ET').first().json.calendarid || null;
} catch (e) {}

const lineas = [];
if (fecha_entrada && fecha_salida) {
  lineas.push(`entrada: ${fecha_entrada}`);
  lineas.push(`salida: ${fecha_salida}`);
}
if (cantidad_personas) lineas.push(`cantidad_personas: ${cantidad_personas}`);
if (calendarid) lineas.push(`calendarId: ${calendarid}`);
if (precio_total) lineas.push(`precio: ${precio_total} ARS`);
if (nombre_cliente) lineas.push(`nombre_cliente: ${nombre_cliente}`);
lineas.push(`error_temporada: ${error_temporada}`);
lineas.push(`derivar_a_vendedor: ${derivar_a_vendedor}`);
lineas.push(`primer_mensaje: ${primer_mensaje}`);

const sistema = lineas.length > 0 ? `\n[SISTEMA] ${lineas.join(' | ')}` : '';

return [{ json: {
  chat_input: messages,
  contexto_sistema: sistema,
  entrada: fecha_entrada,
  salida: fecha_salida,
  primer_mensaje
}}];

const input = $input.first().json;
const mensaje = (input.output || input.text || input.texto_limpio || '').trim();

if (!mensaje) {
  return [{ json: { part1: '', part2: '', part3: '', control: '' } }];
}

const [contenido, control] = mensaje.split('###').map(p => p.trim());

const partes = contenido.split('|||').map(p => p.trim()).filter(p => p.length > 0);

return [{
  json: {
    part1: partes[0] || '',
    part2: partes[1] || '',
    part3: partes[2] || '',
    control: control || ''
  }
}];

