const parsed = $input.item.json;
const fecha_entrada = parsed.fecha_entrada || null;
const fecha_salida = parsed.fecha_salida || null;
const fechas_encontradas = parsed.fechas_encontradas || false;

// NOCHES
let noches = null;
if (fecha_entrada && fecha_salida) {
  const e = new Date(fecha_entrada + 'T12:00:00');
  const s = new Date(fecha_salida + 'T12:00:00');
  noches = Math.round((s - e) / (1000 * 60 * 60 * 24));
}

// TEMPORADA
let temporada = null;
if (fecha_entrada) {
  const e = new Date(fecha_entrada + 'T12:00:00');
  const s = fecha_salida ? new Date(fecha_salida + 'T12:00:00') : null;
  const rangos = [
    { nombre: 'baja_julio', desde: '2026-07-04', hasta: '2026-07-17' },
    { nombre: 'alta_1',     desde: '2026-07-18', hasta: '2026-07-24' },
    { nombre: 'alta_2',     desde: '2026-07-25', hasta: '2026-07-31' },
    { nombre: 'media',      desde: '2026-08-01', hasta: '2026-08-28' },
    { nombre: 'baja_2',     desde: '2026-08-29', hasta: '2026-09-26' },
  ];
  const getTemporada = (fecha) => {
    for (const r of rangos) {
      const desde = new Date(r.desde + 'T12:00:00');
      const hasta = new Date(r.hasta + 'T12:00:00');
      if (fecha >= desde && fecha <= hasta) return r.nombre;
    }
    return null;
  };
  const tempEntrada = getTemporada(e);
  const tempSalida = s ? getTemporada(s) : null;
  if (tempEntrada && tempSalida && tempEntrada !== tempSalida) {
    temporada = 'cruce';
  } else {
    temporada = tempEntrada;
  }
}

// ERROR TEMPORADA
let error_temporada = 0;
if (fecha_entrada || fecha_salida) {
  const e = fecha_entrada ? new Date(fecha_entrada + 'T12:00:00') : null;
  const s = fecha_salida ? new Date(fecha_salida + 'T12:00:00') : null;
  const limiteInicio = new Date('2026-07-04T12:00:00');
  const limiteFin    = new Date('2026-09-26T12:00:00');

  if ((e && (e < limiteInicio || e > limiteFin)) ||
      (s && (s < limiteInicio || s > limiteFin))) {
    error_temporada = 1;
  } else if (
    (fecha_entrada === '2026-07-09' && fecha_salida < '2026-07-12') ||
    fecha_entrada === '2026-07-10' ||
    fecha_entrada === '2026-07-11'
  ) {
    error_temporada = 2;
  } else if (fecha_entrada === '2026-08-16' || fecha_salida === '2026-08-16') {
    error_temporada = 3;
  } else if (
    e && s &&
    e >= new Date('2026-07-18T12:00:00') && e < new Date('2026-07-25T12:00:00') &&
    s > new Date('2026-07-25T12:00:00')
  ) {
    error_temporada = 4;
  } else if (
    (e && e >= new Date('2026-07-18T12:00:00') && e < new Date('2026-07-25T12:00:00') && fecha_salida !== '2026-07-25') ||
    (temporada === 'cruce' && s && s > new Date('2026-07-18T12:00:00') && s < new Date('2026-07-25T12:00:00'))
  ) {
    error_temporada = 5;
  } else if (
    (e && fecha_entrada !== '2026-07-25' && e >= new Date('2026-07-25T12:00:00') && e < new Date('2026-08-01T12:00:00')) ||
    (s && fecha_salida !== '2026-08-01' && s > new Date('2026-07-25T12:00:00') && s <= new Date('2026-08-01T12:00:00'))
  ) {
    error_temporada = 6;
  }
}

// DERIVAR A VENDEDOR por noches
let derivar_a_vendedor = false;
if (error_temporada === 0 && noches !== null && noches < 3) {
  derivar_a_vendedor = true;
}

return [{ json: {
  fecha_entrada,
  fecha_salida,
  fechas_encontradas,
  noches,
  temporada,
  error_temporada,
  derivar_a_vendedor
}}];
